CREATE OR REPLACE PROCEDURE archive_old_orders(p_months INT)
LANGUAGE plpgsql
AS $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN
    SELECT id
    FROM orders
    WHERE created_at < CURRENT_DATE - (p_months || ' months')::INTERVAL
    AND status = 'completed'
  LOOP
    INSERT INTO archived_orders SELECT * FROM orders WHERE id = r.id;
    DELETE FROM orders WHERE id = r.id;
  END LOOP;
  COMMIT;
END;
$$;
